import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def iscoroutinefunction(func):
    # This is a mock of the iscoroutinefunction used in fastapi
    # In reality it's from asyncio or inspect
    return inspect.iscoroutinefunction(func)

def test_async_wrapper_sync_func():
    def sync_func():
        return "sync"

    def wrapper(func):
        @wraps(func)
        async def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(sync_func)
    dep = Dependant(call=wrapped_func)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is True

def test_sync_wrapper_async_func():
    async def async_func():
        return "async"

    def wrapper(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(async_func)
    dep = Dependant(call=wrapped_func)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is True

def test_partial_async_wrapper_sync_func():
    def sync_func():
        return "sync"

    def wrapper(func):
        @wraps(func)
        async def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(sync_func)
    partial_func = partial(wrapped_func)
    dep = Dependant(call=partial_func)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
