import asyncio
import inspect
from functools import wraps, partial

# Mocking the iscoroutinefunction as it is in fastapi
def iscoroutinefunction(func):
    return inspect.iscoroutinefunction(func)

def _is_async_callable(call):
    if call is None:
        return False

    # Check if the current call is async
    if inspect.isroutine(call) and iscoroutinefunction(call):
        return True

    # Check if it's a partial
    if isinstance(call, partial):
        return _is_async_callable(call.func)

    # Check if it's wrapped
    if hasattr(call, "__wrapped__"):
        return _is_async_callable(call.__wrapped__)

    # Check if it's a callable object (not a routine)
    if not inspect.isroutine(call) and hasattr(call, "__call__"):
        return _is_async_callable(call.__call__)

    return False

def test_async_wrapper_sync_func():
    def sync_func():
        return "sync"

    def wrapper(func):
        @wraps(func)
        async def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(sync_func)
    print(f"test_async_wrapper_sync_func: {_is_async_callable(wrapped_func)}")
    assert _is_async_callable(wrapped_func) is True

def test_sync_wrapper_async_func():
    async def async_func():
        return "async"

    def wrapper(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(async_func)
    print(f"test_sync_wrapper_async_func: {_is_async_callable(wrapped_func)}")
    assert _is_async_callable(wrapped_func) is True

def test_partial_async_wrapper_sync_func():
    def sync_func():
        return "sync"

    def wrapper(func):
        @wraps(func)
        async def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(sync_func)
    partial_func = partial(wrapped_func)
    print(f"test_partial_async_wrapper_sync_func: {_is_async_callable(partial_func)}")
    assert _is_async_callable(partial_func) is True

def test_partial_sync_wrapper_async_func():
    async def async_func():
        return "async"

    def wrapper(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    wrapped_func = wrapper(async_func)
    partial_func = partial(wrapped_func)
    print(f"test_partial_sync_wrapper_async_func: {_is_async_callable(partial_func)}")
    assert _is_async_callable(partial_func) is True

class AsyncCallable:
    async def __call__(self):
        return 1

def test_async_callable_object():
    obj = AsyncCallable()
    print(f"test_async_callable_object: {_is_async_callable(obj)}")
    assert _is_async_callable(obj) is True

class SyncCallable:
    def __call__(self):
        return 1

def test_sync_callable_object():
    obj = SyncCallable()
    print(f"test_sync_callable_object: {_is_async_callable(obj)}")
    assert _is_async_callable(obj) is False

if __name__ == "__main__":
    test_async_wrapper_sync_func()
    test_sync_wrapper_async_func()
    test_partial_async_wrapper_sync_func()
    test_partial_sync_wrapper_async_func()
    test_async_callable_object()
    test_sync_callable_object()
    print("All tests passed!")

